// Input validation and data extraction
const body = $input.first().json.body || $input.first().json;

if (!body.articleId || !body.videoUrl || !body.audioUrl) {
  throw new Error('Required fields missing: articleId, videoUrl, audioUrl');
}

return {
  json: {
    articleId: body.articleId,
    title: body.title || `Article ${body.articleId}`,
    videoUrl: body.videoUrl,
    audioUrl: body.audioUrl,
    subtitleUrl: body.subtitleUrl || null,
    duration: body.duration || 45,
    createdAt: new Date().toISOString()
  }
};

// Fetch Hub Context
const articleId = $input.first().json.articleId;
const NOTION_TOKEN = process.env.NOTION_API_TOKEN;
const HUB_DB_ID = '2a268d5c-2986-813c-a8e5-eba390fb71fd';

const searchPayload = {
  filter: {
    property: 'Article ID',
    rich_text: {
      equals: articleId
    }
  }
};

try {
  const response = await $http.post(
    `https://api.notion.com/v1/databases/${HUB_DB_ID}/query`,
    {
      headers: {
        'Authorization': `Bearer ${NOTION_TOKEN}`,
        'Notion-Version': '2022-06-28',
        'Content-Type': 'application/json'
      },
      body: searchPayload
    }
  );

  let hubPageId;
  if (!response.results || response.results.length === 0) {
    throw new Error('Hub entry not found. Phase3 must complete first.');
  } else {
    hubPageId = response.results[0].id;
  }

  return {
    json: {
      ...($input.first().json),
      hubContext: {
        hubPageId,
        articleId
      }
    }
  };
} catch (error) {
  throw new Error(`Hub context fetch failed: ${error.message}`);
}

// Prepare Creatomate render payload
const data = $input.first().json;
const WEBHOOK_BASE = 'https://n8n-python-production-344b.up.railway.app/webhook';

// Creatomate template ID (環境変数から取得するか、ハードコード)
const CREATOMATE_TEMPLATE_ID = process.env.CREATOMATE_TEMPLATE_ID || 'your-template-id';

const renderPayload = {
  template_id: CREATOMATE_TEMPLATE_ID,
  modifications: {
    // 動画レイヤー
    "video-1": {
      source: data.videoUrl,
      trim_duration: data.duration
    },
    // 音声レイヤー
    "audio-1": {
      source: data.audioUrl,
      volume: 1.0
    },
    // タイトルテキスト
    "text-title": {
      text: data.title,
      font_size: 48,
      color: "#FFFFFF"
    }
  },
  render_settings: {
    format: "mp4",
    quality: "high",
    resolution: "1080x1920", // 縦型動画
    fps: 30,
    codec: "h264",
    webhook_url: `${WEBHOOK_BASE}/wf7-render-callback`
  },
  metadata: {
    articleId: data.articleId,
    hubPageId: data.hubContext.hubPageId,
    title: data.title,
    originalVideoUrl: data.videoUrl,
    originalAudioUrl: data.audioUrl
  }
};

// 字幕がある場合は追加
if (data.subtitleUrl) {
  renderPayload.modifications["subtitle-1"] = {
    source: data.subtitleUrl,
    style: {
      font_size: 32,
      color: "#FFFF00",
      background_color: "rgba(0,0,0,0.5)"
    }
  };
}

return {
  json: {
    creatomatePayload: renderPayload,
    hubContext: data.hubContext,
    articleId: data.articleId
  }
};

// Process Creatomate response and update Hub
const response = $input.first().json;
const previousNode = $('Creatomateペイロード作成').first().json;

if (!response.id) {
  throw new Error('Creatomate render ID not received');
}

const updatePayload = {
  properties: {
    'Workflow Status': {
      select: {
        name: 'Rendering'
      }
    },
    'Latest Execution ID': {
      rich_text: [{
        text: {
          content: response.id || 'creatomate-' + Date.now()
        }
      }]
    },
    'Updated At': {
      date: {
        start: new Date().toISOString()
      }
    },
    'Error Log': {
      rich_text: [{
        text: {
          content: `Render started: ${response.id}\nStatus: ${response.status || 'processing'}\nEstimated time: 1-3 minutes`
        }
      }]
    }
  }
};

return {
  json: {
    hubPageId: previousNode.hubContext.hubPageId,
    updatePayload,
    creatomateRenderId: response.id,
    creatomateStatus: response.status || 'processing',
    articleId: previousNode.articleId
  }
};
